export interface EditorStyle {
  css?: string;
  isGlobalStyles?: boolean;
  __unstableType?: string;
}

/**
 * Whether an editor style is a theme global style regenerated by the editor.
 *
 * With a block theme, the editor regenerates the theme's global styles in the
 * browser and adds them to the editor settings without a type.
 *
 * @param {EditorStyle} style An editor style.
 * @returns {boolean}
 */
const isThemeGlobalStyle = (style: EditorStyle): boolean => (
  // eslint-disable-next-line no-underscore-dangle
  !!style.isGlobalStyles && !style.__unstableType
);

export default isThemeGlobalStyle;
